import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
    // Arrange: sign in so the session cookie is set on this request context
    const login = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: PASSWORD },
    });
    expect(login.status(), await login.text()).toBe(200);

    // Act
    const logout = await request.post("/api/auth/logout");

    // Assert
    const body = await logout.text();
    expect(logout.status(), body).toBe(204);

    const setCookies = logout
      .headersArray()
      .filter((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="))
      .map((h) => h.value);
    expect(setCookies.length, `no session Set-Cookie in logout response: ${body}`).toBeGreaterThan(0);

    const cleared = setCookies.some((value) => {
      const lower = value.toLowerCase();
      const emptyValue = /^session=(;|$)/.test(value);
      const expiredNow = lower.includes("max-age=0");
      const expiredDate = lower.includes("expires=thu, 01 jan 1970");
      return emptyValue || expiredNow || expiredDate;
    });
    expect(cleared, `session cookie not cleared: ${setCookies.join(" | ")}`).toBe(true);
  });
});
